def mask_tokens(tokens, mask_id, mask_prob=0.15):
    masked = tokens.copy(); labels = [-100]*len(tokens)
    for i in range(len(tokens)):
        if np.random.random() < mask_prob:
            labels[i] = tokens[i]; masked[i] = mask_id
