def mlm_loss(logits, target_ids):
    loss=0;n=0
    for logit,tid in zip(logits,target_ids):
        if tid<0: continue
        exp=np.exp(logit-np.max(logit)); probs=exp/np.sum(exp)
        loss+=-np.log(probs[tid]+1e-10);n+=1
    return round(float(loss/n),4) if n else 0

import numpy as np
def scaled_dot_product_attention(Q,K,V):
    d_k = Q.shape[-1]
    scores = Q @ K.T / np.sqrt(d_k)
    exp_s = np.exp(scores-np.max(scores,axis=-1,keepdims=True))
    weights = exp_s / np.sum(exp_s,axis=-1,keepdims=True)
    return {'output': weights @ V, 'weights': weights}
def self_attention(X, W_q, W_k, W_v):
    return scaled_dot_product_attention(X@W_q, X@W_k, X@W_v)

import numpy as np
def split_heads(X, h):
    n,d = X.shape
    return X.reshape(n,h,d//h).transpose(1,0,2)
def concat_heads(heads):
    h,n,dh = heads.shape
    return heads.transpose(1,0,2).reshape(n,h*dh)
def multi_head_attention(X, p, h):
    Q = X@p['Wq']; K = X@p['Wk']; V = X@p['Wv']
    heads = []
    for i in range(h):
        qi = split_heads(Q,h)[i]; ki = split_heads(K,h)[i]; vi = split_heads(V,h)[i]
        dk = qi.shape[-1]
        scores = qi@ki.T/np.sqrt(dk)
        exp_s = np.exp(scores-np.max(scores,axis=-1,keepdims=True))
        attn = exp_s/np.sum(exp_s,axis=-1,keepdims=True)
        heads.append(attn@vi)
    cat = concat_heads(np.array(heads))
    return {'output': cat@p['Wo'], 'heads': heads}

import re
def get_stats(vocab):
  pairs={}
  for word,tokens in vocab.items():
    for i in range(len(tokens)-1):
      pair=(tokens[i],tokens[i+1])
      pairs[pair]=pairs.get(pair,0)+len(tokens)
  return pairs
def merge_vocab(pair,vocab):
  new={}
  for word,tokens in vocab.items():
    nt=[];i=0
    while i<len(tokens):
      if i<len(tokens)-1 and (tokens[i],tokens[i+1])==pair:
        nt.append(tokens[i]+tokens[i+1]);i+=2
      else:nt.append(tokens[i]);i+=1
    new[word]=nt
  return new
def bpe_tokenize(word,merges,n):
  vocab={word:list(word)}
  for _ in range(n):
    p=get_stats(vocab)
    if not p:break
    best=max(p,key=p.get)
    vocab=merge_vocab(best,vocab)
  return vocab[word]

import math
def bm25(query,docs,k1=1.5,b=0.75):
  N=len(docs);avgDL=sum(len(d)for d in docs)/N
  scores=[]
  for i,doc in enumerate(docs):
    score=0;dl=len(doc)
    for q in query.split():
      tf=doc.count(q)
      df=sum(1 for d in docs if q in d)
      idf=math.log((N-df+0.5)/(df+0.5)+1)
      score+=idf*(tf*(k1+1))/(tf+k1*(1-b+b*dl/avgDL))
    scores.append((i,round(score,4)))
  return sorted(scores,key=lambda x:-x[1])

