import numpy as np
def softmax(x):
  xm=x-np.max(x,axis=-1,keepdims=True);e=np.exp(xm);return e/np.sum(e,axis=-1,keepdims=True)
def multihead_attention(X,Wq,Wk,Wv,Wo,h=2):
  n,d=X.shape;dk=d//h;Q=X@Wq;K=X@Wk;V=X@Wv;heads=[]
  for i in range(h):
    qi=Q[:,i*dk:(i+1)*dk];ki=K[:,i*dk:(i+1)*dk];vi=V[:,i*dk:(i+1)*dk]
    scores=qi@ki.T/np.sqrt(dk);w=softmax(scores);heads.append(w@vi)
  return np.concatenate(heads,axis=1)@Wo
def get_weights(X,Wq,Wk,h=2):
  n,d=X.shape;dk=d//h;Q=X@Wq;K=X@Wk;ws=[]
  for i in range(h):
    scores=Q[:,i*dk:(i+1)*dk]@K[:,i*dk:(i+1)*dk].T/np.sqrt(dk)
    ws.append(softmax(scores))
  return ws
